Express $43210_{6}-3210_{7}$ in base 10.

Put your final answer within \boxed{}.

#include <iostream>
#include <string>
#include <cmath>

int main() {
    std::string base64 = "43210_6";
    std::string base7 = "3210_7";

    int base64Value = 0;
    int base7Value = 0;

    for (char c : base64) {
        if (c >= '0' && c <= '9') {
            base64Value = base64Value * 10 + (c - '0');
        } else if (c >= 'A' && c <= 'Z') {
            base64Value = base64Value * 10 + (c - 'A' + 10);
        }
    }

    for (char c : base7) {
        if (c >= '0' && c <= '9') {
            base7Value = base7Value * 10 + (c - '0');
        } else if (c >= 'A' && c <= 'Z') {
            base7Value = base7Value * 10 + (c - 'A' + 10);
        }
    }

    int result = base64Value - base7Value;

    std::cout << "The result in base 10 is: " << result << std::endl;

    return 0;
}
